642	+
643	+/**
644	+ * The GL diagnostic's sheet: the layers one under the other, each under a
645	+ * row with its name, its colours on the left and its alpha beside them -
646	+ * the glow packs colony ids into its alpha, so that is half of what to see.
647	+ */
648	+export function sheetLayout(
649	+  layers: readonly Pick<CapturedLayer, 'label' | 'width' | 'height'>[]
650	+): { width: number; height: number; placements: SheetPlacement[] } {
651	+  let top = 0;
652	+  const placements = layers.map(({ label, width, height }) => {
653	+    const placement = {
654	+      label,
655	+      labelY: top,
656	+      imageY: top + LABEL_HEIGHT,
657	+      alphaX: width,
658	+    };
659	+    top += LABEL_HEIGHT + height;
660	+    return placement;
661	+  });
662	+  return {
663	+    width: Math.max(0, ...layers.map((layer) => layer.width * 2)),
664	+    height: top,
665	+    placements,
666	+  };
667	+}
668	+
669	+/** A layer's RGBA as its colours, opaque, and its alpha as grey. */
670	+export function splitAlpha(pixels: Uint8Array): {
671	+  colors: Uint8ClampedArray<ArrayBuffer>;
672	+  alpha: Uint8ClampedArray<ArrayBuffer>;
673	+} {
674	+  const colors = new Uint8ClampedArray(pixels);
675	+  const alpha = new Uint8ClampedArray(pixels.length);
676	+  for (let i = 0; i < pixels.length; i += 4) {
677	+    colors[i + 3] = 255;
678	+    alpha.fill(pixels[i + 3], i, i + 3);
679	+    alpha[i + 3] = 255;
680	+  }
681	+  return { colors, alpha };
682	+}
683	+
684	+/** Draws the sheet of the layers - null where the canvas gives no 2D context. */
685	+function drawSheet(layers: readonly CapturedLayer[]): HTMLCanvasElement | null {
686	+  const { width, height, placements } = sheetLayout(layers);
687	+  const canvas = document.createElement('canvas');
688	+  canvas.width = width;
689	+  canvas.height = height;
690	+  const cx = canvas.getContext('2d');
691	+  if (cx == null) {
692	+    return null;
693	+  }
694	+  cx.fillStyle = '#000';
695	+  cx.fillRect(0, 0, width, height);
696	+  cx.font = `${LABEL_HEIGHT - 4}px monospace`;
697	+  cx.textBaseline = 'top';
698	+  layers.forEach((layer, index) => {
699	+    const { label, labelY, imageY, alphaX } = placements[index];
700	+    cx.fillStyle = '#fff';
701	+    cx.fillText(
702	+      `${label} (${layer.width}×${layer.height}) · alpha`,
703	+      2,
704	+      labelY + 2
705	+    );
706	+    const { colors, alpha } = splitAlpha(layer.pixels);
707	+    cx.putImageData(
708	+      new ImageData(colors, layer.width, layer.height),
709	+      0,
710	+      imageY
711	+    );
712	+    cx.putImageData(
713	+      new ImageData(alpha, layer.width, layer.height),
714	+      alphaX,
715	+      imageY
716	+    );
717	+  });
718	+  return canvas;
719	+}
