723	+ * browser's download - on a phone too, which has no dev tools to read them
724	+ * with.
725	+ */
726	+export function downloadLayerSheet(layers: readonly CapturedLayer[]): void {
727	+  if (layers.length === 0) {
728	+    console.warn('GL layers: no GL painter is diagnosed, nothing to save');
729	+    return;
730	+  }
731	+  const canvas = drawSheet(layers);
732	+  if (canvas == null) {
733	+    console.warn('GL layers: the browser gave no canvas to draw them on');
734	+    return;
735	+  }
736	+  canvas.toBlob((blob) => {
737	+    if (blob == null) {
738	+      console.warn(
739	+        `GL layers: the browser could not encode the ${canvas.width}×${canvas.height} sheet`
740	+      );
741	+      return;
742	+    }
743	+    const url = URL.createObjectURL(blob);
744	+    const link = document.createElement('a');
745	+    link.href = url;
746	+    link.download = `bacteria-gl-layers-${new Date().toISOString().replace(/[:.]/g, '-')}.png`;
747	+    link.click();
748	+    // A phone may still be fetching it when the click returns.
749	+    setTimeout(() => URL.revokeObjectURL(url), REVOKE_AFTER_MS);
750	+  }, 'image/png');
751	+}
